CREATE TABLE business_leads (id TEXT PRIMARY KEY NOT NULL, business_name TEXT NOT NULL CHECK (length(trim(business_name)) > 0 AND business_name = trim(business_name)), source_kind TEXT NOT NULL CHECK (source_kind IN ('manual', 'discovery')), source_provider TEXT, source_reference TEXT NOT NULL CHECK (length(trim(source_reference)) > 0 AND source_reference = trim(source_reference)), status TEXT NOT NULL CHECK (status IN ('recorded', 'reviewing', 'archived')), website_presence TEXT NOT NULL CHECK (website_presence IN ('unknown', 'present', 'missing')), website_url TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL CHECK (typeof(version) = 'integer' AND version > 0), CHECK ((website_presence = 'present' AND website_url IS NOT NULL AND length(trim(website_url)) > 0) OR (website_presence IN ('unknown', 'missing') AND website_url IS NULL)), CHECK ((source_kind = 'manual' AND source_provider IS NULL) OR (source_kind = 'discovery' AND source_provider IS NOT NULL AND length(source_provider) BETWEEN 1 AND 64 AND substr(source_provider, 1, 1) GLOB '[a-z]' AND source_provider NOT GLOB '*[^a-z0-9_]*' AND length(source_reference) <= 512)));
CREATE UNIQUE INDEX business_leads_discovery_identity_idx ON business_leads (source_provider, source_reference) WHERE source_kind = 'discovery';
CREATE TABLE single_page_crawl_evidence (id INTEGER PRIMARY KEY, lead_id TEXT NOT NULL, lead_version INTEGER NOT NULL CHECK (typeof(lead_version) = 'integer' AND lead_version > 0), outcome TEXT NOT NULL CHECK (outcome IN ('fetched', 'failed')), requested_url TEXT NOT NULL CHECK (length(trim(requested_url)) > 0 AND requested_url = trim(requested_url)), attempted_at TEXT NOT NULL CHECK (length(attempted_at) = 24 AND substr(attempted_at, 1, 4) GLOB '[0-9][0-9][0-9][0-9]' AND substr(attempted_at, 5, 1) = '-' AND substr(attempted_at, 6, 2) GLOB '[0-9][0-9]' AND substr(attempted_at, 8, 1) = '-' AND substr(attempted_at, 9, 2) GLOB '[0-9][0-9]' AND substr(attempted_at, 11, 1) = 'T' AND substr(attempted_at, 12, 2) GLOB '[0-9][0-9]' AND substr(attempted_at, 14, 1) = ':' AND substr(attempted_at, 15, 2) GLOB '[0-9][0-9]' AND substr(attempted_at, 17, 1) = ':' AND substr(attempted_at, 18, 2) GLOB '[0-9][0-9]' AND substr(attempted_at, 20, 1) = '.' AND substr(attempted_at, 21, 3) GLOB '[0-9][0-9][0-9]' AND substr(attempted_at, 24, 1) = 'Z' AND CAST(substr(attempted_at, 6, 2) AS INTEGER) BETWEEN 1 AND 12 AND CAST(substr(attempted_at, 9, 2) AS INTEGER) BETWEEN 1 AND 31 AND CAST(substr(attempted_at, 12, 2) AS INTEGER) BETWEEN 0 AND 23 AND CAST(substr(attempted_at, 15, 2) AS INTEGER) BETWEEN 0 AND 59 AND CAST(substr(attempted_at, 18, 2) AS INTEGER) BETWEEN 0 AND 59 AND date(substr(attempted_at, 1, 10)) = substr(attempted_at, 1, 10) AND strftime('%Y-%m-%dT%H:%M:%fZ', attempted_at) IS NOT NULL AND strftime('%Y-%m-%dT%H:%M:%fZ', attempted_at) = attempted_at), final_url TEXT CHECK (final_url IS NULL OR (length(trim(final_url)) > 0 AND final_url = trim(final_url))), status_code INTEGER, content_type TEXT, body_text TEXT, byte_length INTEGER, redirect_count INTEGER, failure_code TEXT, CHECK ((outcome = 'fetched' AND final_url IS NOT NULL AND status_code IS NOT NULL AND typeof(status_code) = 'integer' AND status_code = 200 AND content_type IS NOT NULL AND content_type IN ('text/html', 'application/xhtml+xml') AND body_text IS NOT NULL AND byte_length IS NOT NULL AND typeof(byte_length) = 'integer' AND byte_length >= 0 AND byte_length <= 1048576 AND byte_length = length(CAST(body_text AS BLOB)) AND redirect_count IS NOT NULL AND typeof(redirect_count) = 'integer' AND redirect_count >= 0 AND redirect_count <= 5 AND failure_code IS NULL) OR (outcome = 'failed' AND final_url IS NULL AND status_code IS NULL AND content_type IS NULL AND body_text IS NULL AND byte_length IS NULL AND redirect_count IS NULL AND failure_code IS NOT NULL AND failure_code IN ('INVALID_URL', 'UNSUPPORTED_SCHEME', 'CREDENTIALS_NOT_ALLOWED', 'PORT_NOT_ALLOWED', 'BLOCKED_HOST', 'BLOCKED_ADDRESS', 'DNS_RESOLUTION_FAILED', 'CANCELLED', 'TIMEOUT', 'NETWORK_FAILURE', 'REDIRECT_LIMIT', 'REDIRECT_DOWNGRADE', 'HTTP_FAILURE', 'UNSUPPORTED_CONTENT_TYPE', 'UNSUPPORTED_CONTENT_ENCODING', 'RESPONSE_TOO_LARGE', 'INVALID_BODY'))), FOREIGN KEY (lead_id) REFERENCES business_leads(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TRIGGER single_page_crawl_evidence_prevent_update BEFORE UPDATE ON single_page_crawl_evidence BEGIN SELECT RAISE(ABORT, 'single_page_crawl_evidence is append-only'); END;
CREATE TRIGGER single_page_crawl_evidence_prevent_delete BEFORE DELETE ON single_page_crawl_evidence BEGIN SELECT RAISE(ABORT, 'single_page_crawl_evidence is append-only'); END;
